[GLOBAL]
// ---- helpers -------------------------------------------------------------
#define GAUSSF(x, mu, sd) (exp(-0.5*((x)-(mu))*((x)-(mu))/((sd)*(sd))))
#define SIGM(x, x0, k)    (1.0/(1.0+exp(-((x)-(x0))/(k))))
#define CLAMP01(x)        ((x) < 0.0 ? 0.0 : ((x) > 1.0 ? 1.0 : (x)))
#define POSPART(x)        ((x) < 0.0 ? 0.0 : (x))

// ---- quantities shared between [ODE] and [TABLE] -------------------------
namespace {
  double cday, E2_TOT, a5ar, ssri_eq, occ, load, sens, ns_drive, eff;
  double chg, WE2, PROG, gnrh_eff, hypo, sleep_q, bz_occ;
}

[ODE]
cday = fmod(SOLVERTIME, TCYC) + 1.0;                 // cycle day, 1..29

// ═══════════════════════════════ drug PK ═════════════════════════════════
dxdt_SERT_D = -KA_SERT*SERT_D;
dxdt_SERT_C =  KA_SERT*SERT_D/V_SERT*1000.0 - K_SERT*SERT_C;
dxdt_DMS_C  =  FM_DMS*K_SERT*SERT_C - K_DMS*DMS_C;
dxdt_FLX_C  = -K_FLX*FLX_C;
dxdt_NFLX_C =  FM_NFLX*K_FLX*FLX_C - K_NFLX*NFLX_C;
dxdt_DRSP_D = -KA_DRSP*DRSP_D;
dxdt_DRSP_C =  KA_DRSP*DRSP_D/V_DRSP*1000.0 - K_DRSP*DRSP_C;
dxdt_LEUP_D = -KA_LEUP*LEUP_D;
dxdt_LEUP_C =  KA_LEUP*LEUP_D/V_LEUP*1000.0 - K_LEUP*LEUP_C;
dxdt_SEPRA_D= -KA_SEPRA*SEPRA_D;
dxdt_SEPRA_C=  KA_SEPRA*SEPRA_D/V_SEPRA*1000.0 - K_SEPRA*SEPRA_C;
dxdt_DUTA_D = -KA_DUTA*DUTA_D;
dxdt_DUTA_C =  KA_DUTA*DUTA_D/V_DUTA*1000.0 - K_DUTA*DUTA_C;
dxdt_ALPZ_D = -KA_ALPZ*ALPZ_D;
dxdt_ALPZ_C =  KA_ALPZ*ALPZ_D/V_ALPZ*1000.0 - K_ALPZ*ALPZ_C;
dxdt_UPA_C  = -K_UPA*UPA_C;
dxdt_ZUR    = -K_ZUR*ZUR;

// ═══════════════════════ gonadotropin suppression ════════════════════════
double supp_oc  = DRSP_C/(DRSP_C + EC50_SUPP);
double supp_upa = UPA_C/(UPA_C + EC50_UPA_SUPP);
double leup_norm= LEUP_C/(LEUP_C + EC50_LEUP);
dxdt_PITDS = K_DS_ON*leup_norm*(1.0 - PITDS) - K_DS_OFF*PITDS;
// GnRH agonist: flare while PITDS is still low, profound suppression later
gnrh_eff = (1.0 - PITDS)*(1.0 + AGON_FLARE*leup_norm*(1.0 - PITDS));
gnrh_eff *= (1.0 - supp_oc)*(1.0 - 0.55*supp_upa);
gnrh_eff /= (1.0 + POSPART(P4)/KP4_FB);              // luteal P4 feedback
if (gnrh_eff < 0.0) gnrh_eff = 0.0;

// ═══════════════════════════ HPO cycle engine ════════════════════════════
dxdt_FSH = KFSH_IN*gnrh_eff/(1.0 + FOLL/KINH) - KFSH_OUT*FSH;
double surge = SURGE_AMP*GAUSSF(cday, SURGE_DAY, SURGE_SD)
             * CLAMP01((FOLL - 0.25)/0.35)*gnrh_eff;
dxdt_LH = KLH_IN*gnrh_eff + surge - KLH_OUT*LH;

double gonad = (OOPH > 0.5) ? 0.0 : 1.0;
double ovul_flux = KOV*FOLL*GAUSSF(cday, OVUL_DAY, OVUL_SD)
                 * CLAMP01((LH - 2.5)/6.0)*gonad;
// A fresh follicular cohort is recruited each cycle (REC) and then grows
// autocatalytically; the FSH response saturates (KFSH_M) so that the very high
// early-follicular FSH cannot drive explosive growth.
double hfsh = POSPART(FSH - FSH_THR);
hfsh = hfsh/(KFSH_M + hfsh);
dxdt_FOLL = (REC + KFG*FOLL)*hfsh*(1.0 - FOLL/FMAX)*gonad
          - KFL*FOLL - ovul_flux;

double klut = KLUT0 + KLUT1*SIGM(cday, LUT_REG_DAY, LUT_REG_SD);
// CL growth is gated to the post-ovulatory window so that a numerically small
// CL remnant cannot regrow during the follicular phase.
double w_lut = SIGM(cday, 14.8, 0.5)*(1.0 - SIGM(cday, 24.5, 0.7));
double grow  = (CL > 0.02) ? KCL_G*CL*(1.0 - CL/CL_MAX)*w_lut : 0.0;
dxdt_CL = KCL*ovul_flux + grow - klut*CL;

double ab = (SOLVERTIME >= ADDBACK_T0) ? 1.0 : 0.0;
dxdt_E2 = KE2F*pow(FOLL, E2_HILL) + KE2L*CL - KE2_OUT*(E2 - E2_BASE)
        + ab*ADDBACK_E2;
dxdt_P4 = KP4*CL - KP4_OUT*(P4 - P4_BASE) + ab*ADDBACK_P4;

// Ethinylestradiol is not in the E2 state but it IS estrogenic: every
// estrogen-receptor-mediated readout below therefore sees E2_TOT.
E2_TOT = E2 + EE_E2EQ*(DRSP_C/(DRSP_C + 5.0));

// ══════════════════════ neurosteroidogenesis ═════════════════════════════
a5ar    = 1.0/(1.0 + DUTA_C/IC50_5AR1);
ssri_eq = SERT_C + POT_DMS*DMS_C + POT_FLX*(FLX_C + NFLX_C);
double f_hsd = 1.0 + EMAX_HSD*ssri_eq/(EC50_HSD + ssri_eq);

dxdt_DHP   = K5AR*a5ar*POSPART(P4) - KDHP*DHP;
dxdt_ALLOP = K3HSD*f_hsd*DHP + ADR_ALLO*a5ar - KALLOP*ALLOP;
dxdt_ALLOB = KIN_B*ALLOP + DENOVO*(1.0 + W_STRESS_NS*STRESS)*a5ar
           - KOUT_B*ALLOB;
dxdt_ISOB  = SEPRA_BRAIN*SEPRA_C - KISO_OUT*ISOB;

// ═════════ GABA-A composition: the slow, SYMMETRIC change detector ═══════
PROG = POSPART(P4)/P4REF + 1.4*DRSP_C/(DRSP_C + KI_PR);
double ALLO_EFF = ALLOB + ZUR;               // exogenous analogues are sensed too
dxdt_MALLO = (ALLO_EFF - MALLO)/TAU_M;
dxdt_MPROG = (PROG - MPROG)/TAU_MP;
if (RATE_OFF > 0.5) {
  chg = 0.0;
  WE2 = 0.0;
} else {
  double fall_a = POSPART((MALLO - ALLO_EFF)/(MALLO + 0.5));
  double rise_a = POSPART((ALLO_EFF - MALLO)/(MALLO + 0.5));
  double fall_p = POSPART((MPROG - PROG)/(MPROG + 0.25));
  double rise_p = POSPART((PROG - MPROG)/(MPROG + 0.25));
  chg = (fall_a + KRISE*rise_a) + W_PROG*(fall_p + KRISE*rise_p);
  WE2 = POSPART((ME2 - E2_TOT)/(ME2 + 20.0));
}
double delta_ss = 1.0 + HD*ALLOB/(KD + ALLOB);
double a4_ss    = 1.0 + HA*chg/(KA + chg);
dxdt_DELTA  = (delta_ss - DELTA)/TAU_D;
dxdt_ALPHA4 = (a4_ss - ALPHA4)/TAU_A4;
dxdt_ME2    = (E2_TOT - ME2)/TAU_ME2;

// ══════════════ inverted-U neurosteroid transduction ═════════════════════
sens = 1.0 + GAMMA_D*(DELTA - 1.0) + GAMMA_A4*(ALPHA4 - 1.0);
double bz = BZEQ*ALPZ_C/(1.0 + 0.60*(ALPHA4 - 1.0));
load = (ALLOB + PREG_EQ + bz + ZUR)/(1.0 + ISOB/KI_ISO);
if (MONOTONE > 0.5) {
  // Level detector.  MONO_GAIN is chosen so the falsified model reaches the
  // SAME peak drive as the base model on an untreated cycle, so that the
  // comparison cannot be rigged by a difference of scale.
  ns_drive = MONO_GAIN*load/KP;
} else {
  double r = load/KP;
  ns_drive = sens*r*exp(1.0 - r);
}
ns_drive *= (1.0 - CA_SUPP);
eff = pow(ns_drive, NS_HILL)/(pow(ns_drive, NS_HILL) + pow(NS50, NS_HILL));

// ═════════════════════════════ serotonin ═════════════════════════════════
occ = OCC_MAX*ssri_eq/(ssri_eq + EC50_SERT);
double brake = WB*POSPART(SHT - 1.0)*(1.0 - DES);
dxdt_SHT = KS_SYN/(1.0 + brake) - KS_OUT*(1.0 - occ)*SHT - K5HT_NS*eff*SHT;
double des_t = KD2*POSPART(SHT - 1.0);
if (des_t > 1.0) des_t = 1.0;
dxdt_DES  = (des_t - DES)/TAU_DES;
dxdt_BDNF = (KBDNF*POSPART(SHT - 1.0) - BDNF)/TAU_BDNF;

// ══════════════════════════════ HPA axis ═════════════════════════════════
double allo_brake = K_ALLO_BRAKE*(ALLOB/(ALLOB + 2.0))/sens;
dxdt_CRH  = ((STRESS + 0.7)*(1.0 - allo_brake)/(1.0 + 0.8*(CORT - 1.0)) - CRH)
          / TAU_CRH;
dxdt_ACTH = (CRH - ACTH)/TAU_ACTH;
dxdt_CORT = (ACTH - CORT)/TAU_CORT;

// ═══════════════════════════ corticolimbic ═══════════════════════════════
bz_occ = ALPZ_C/(ALPZ_C + 8.0)/(1.0 + 0.60*(ALPHA4 - 1.0));
double prog_ex = DRSP_C/(DRSP_C + KI_PR);
double amy_ss = 1.0 + W_NS_AMY*eff + W_CORT_AMY*(CORT/CORT0 - 1.0)
              - W_SHT_AMY*POSPART(SHT - 1.0) - W_PFC_AMY*(PFC - 1.0)
              - W_BZ_AMY*bz_occ + W_PROG_AMY*prog_ex;
double pfc_ss = 1.0 - P_NS_PFC*eff + P_E2_PFC*(E2_TOT/E2REF - 1.0) + CBT;
double rew_ss = 1.0 - R_NS_REW*eff + R_BDNF*BDNF - R_WE2*WE2;
if (amy_ss < 0.2) amy_ss = 0.2;
if (pfc_ss < 0.2) pfc_ss = 0.2;
if (rew_ss < 0.2) rew_ss = 0.2;
dxdt_AMY = (amy_ss - AMY)/TAU_AMY;
dxdt_PFC = (pfc_ss - PFC)/TAU_PFC;
dxdt_REW = (rew_ss - REW)/TAU_REW;

// ═════════════════════════════ somatic ═══════════════════════════════════
dxdt_ALDO = (1.0 + A_P4*POSPART(P4)/P4REF - ALDO)/TAU_ALDO;
double mr_block = 1.0/(1.0 + DRSP_C/KI_MR_DRSP + SPIRO/KI_MR_SPIRO
                       + POSPART(P4)/KI_MR_P4);
dxdt_ECFV = (1.0 + ECF_GAIN*ALDO*mr_block - ECFV)/TAU_ECFV;
double pr_block = 1.0/(1.0 + UPA_C/UPA_PR_KI);
double br_ss = B_E2*E2_TOT/E2REF
             + B_P4*(POSPART(P4)/P4REF + prog_ex)*pr_block;
dxdt_BREAST = (br_ss - BREAST)/TAU_BR;
// perimenstrual prostaglandin window (cycle day ~27 through day ~3)
double pgw = 0.0;
if (cday >= 26.5)     pgw = SIGM(cday, 27.0, 0.5);
else if (cday <= 3.5) pgw = 1.0 - SIGM(cday, 3.0, 0.6);
dxdt_PGE = (KPG*pgw*(1.0 - NSAID)*((OOPH > 0.5) ? 0.0 : 1.0) - PGE)/TAU_PG;

// ═══════════════════════ DRSP symptom domains ════════════════════════════
double ca    = 1.0 - ((CA_SUPP > 0.0) ? 0.25 : 0.0);
double bloat = POSPART((ECFV - 1.0)/0.030);
double cramp = POSPART(PGE);
sleep_q = 1.0 - CLAMP01(0.35*eff + 0.030*HF);
double d_amy  = POSPART(AMY - 1.0);
double d_pfc  = POSPART(1.0 - PFC);
double d_rew  = POSPART(1.0 - REW);
double sht_up = POSPART(SHT - 1.0);
double sht_dn = POSPART(1.0 - SHT);

double f_irr = 0.62*d_amy + 0.22*eff - 0.34*sht_up - 0.18*(PFC - 1.0);
double f_anx = 0.66*d_amy + 0.18*eff - 0.28*sht_up;
double f_lab = 0.55*d_amy + 0.30*d_pfc + 0.15*WE2 - 0.22*sht_up;
double f_dep = 0.42*eff + 0.38*d_rew + 0.18*WE2 - 0.30*BDNF - 0.15*sht_up;
double f_anh = 0.28*eff + 0.62*d_rew - 0.32*BDNF;
double f_cog = 0.52*d_pfc + 0.26*eff + 0.14*(1.0 - sleep_q);
double f_fat = 0.34*eff + 0.32*(1.0 - sleep_q) + 0.22*d_rew;
double f_app = (0.58*eff + 0.30*sht_dn - 0.20*sht_up)*ca;
double f_slp = (1.0 - sleep_q)*1.15;
double f_ovr = 0.58*eff + 0.30*d_pfc - 0.20*sht_up;
double f_phy = (0.34*bloat + 0.34*BREAST + 0.32*cramp)*ca;

dxdt_S_IRR = (1.0 + 5.0*CLAMP01(f_irr + BASE_SYM) - S_IRR)/TAU_S;
dxdt_S_ANX = (1.0 + 5.0*CLAMP01(f_anx + BASE_SYM) - S_ANX)/TAU_S;
dxdt_S_LAB = (1.0 + 5.0*CLAMP01(f_lab + BASE_SYM) - S_LAB)/TAU_S;
dxdt_S_DEP = (1.0 + 5.0*CLAMP01(f_dep + BASE_SYM) - S_DEP)/TAU_S;
dxdt_S_ANH = (1.0 + 5.0*CLAMP01(f_anh + BASE_SYM) - S_ANH)/TAU_S;
dxdt_S_COG = (1.0 + 5.0*CLAMP01(f_cog + BASE_SYM) - S_COG)/TAU_S;
dxdt_S_FAT = (1.0 + 5.0*CLAMP01(f_fat + BASE_SYM) - S_FAT)/TAU_S;
dxdt_S_APP = (1.0 + 5.0*CLAMP01(f_app + BASE_SYM) - S_APP)/TAU_S;
dxdt_S_SLP = (1.0 + 5.0*CLAMP01(f_slp + BASE_SYM) - S_SLP)/TAU_S;
dxdt_S_OVR = (1.0 + 5.0*CLAMP01(f_ovr + BASE_SYM) - S_OVR)/TAU_S;
dxdt_S_PHY = (1.0 + 5.0*CLAMP01(f_phy + BASE_SYM) - S_PHY)/TAU_S;

// ═══════════════════════════ organ / safety ══════════════════════════════
double hf_ss = HF_MAX/(1.0 + (E2_TOT/E50_HF)*(E2_TOT/E50_HF))*(1.0 - HF_SSRI*occ);
dxdt_HF = (hf_ss - HF)/TAU_HF;
hypo = 1.0/(1.0 + (E2_TOT/E50_BMD)*(E2_TOT/E50_BMD));
dxdt_BMD = -KBMD_LOSS*POSPART(hypo - HYPO_REF)
         + KBMD_REC*POSPART(-BMD)*POSPART(HYPO_REF - hypo)/HYPO_REF;
dxdt_ENDO = ((DRSP_C/(DRSP_C + 5.0)) - ENDO)/TAU_ENDO;

[TABLE]
capture cycle_day        = cday;
capture DRSP_11          = S_IRR + S_DEP + S_ANX + S_LAB + S_ANH + S_COG
                         + S_FAT + S_APP + S_SLP + S_OVR + S_PHY;
capture DRSP_CORE        = S_IRR + S_DEP + S_ANX + S_LAB + S_ANH;
capture E2_total         = E2_TOT;
capture NS_load          = load;
capture NS_drive         = ns_drive;
capture NS_sensitivity   = sens;
capture Affective_effect = eff;
capture GnRH_axis_drive  = gnrh_eff;
capture SERT_occupancy   = occ;
capture SRD5A1_activity  = a5ar;
capture Change_signal    = chg;
capture E2_withdrawal    = WE2;
capture Progestogen_tone = PROG;
capture Hypoestrogenism  = hypo;
capture Sleep_quality    = sleep_q;

[CAPTURE]
cycle_day DRSP_11 DRSP_CORE E2_total NS_load NS_drive NS_sensitivity
Affective_effect GnRH_axis_drive SERT_occupancy SRD5A1_activity
Change_signal E2_withdrawal Progestogen_tone Hypoestrogenism Sleep_quality


